import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Field Response Action","description":"","frontmatter":{"prev":{"text":"Field Settings","link":"/documentation/form-fields/field-settings"}},"headers":[],"relativePath":"documentation/form-fields/field-response-action.md","filePath":"documentation/form-fields/field-response-action.md","lastUpdated":1788551488000}`),a={name:`documentation/form-fields/field-response-action.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="field-response-action" tabindex="-1">Field Response Action <a class="header-anchor" href="#field-response-action" aria-label="Permalink to “Field Response Action”">​</a></h1><p>Field Response Actions allow you to define custom automated behaviors triggered immediately when a field operation completes. Depending on the execution outcome—<strong>Success</strong>, <strong>Error</strong>, or <strong>Skip</strong>—you can automate conditional branching, navigate pages, trigger segments, update datasets, or handle error recovery.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>During automation, every field interaction yields an execution status:</p><ul><li><strong>Success</strong>: The target element was located and the configured action (typing, selecting, clicking, or running code) executed without errors.</li><li><strong>Error</strong>: The element could not be found, timed out, or threw a DOM exception during interaction.</li><li><strong>Skip</strong>: The field was intentionally bypassed due to configured skip conditions or missing data rules.</li></ul><p>By attaching response actions to these channels, you transform linear form filling into resilient, intelligent automation pipelines that adapt dynamically to web page behaviors.</p><hr><h2 id="available-action-types" tabindex="-1">Available Action Types <a class="header-anchor" href="#available-action-types" aria-label="Permalink to “Available Action Types”">​</a></h2><p>When configuring a response action for any status channel, you can select from the following actions:</p><table tabindex="0"><thead><tr><th>Action Type</th><th>Behavior</th><th>Key Parameters / Use Cases</th></tr></thead><tbody><tr><td><strong>Open a URL</strong></td><td>Navigates the current browser tab to a specified URL.</td><td>Target URL (supports static URLs or dynamic variables). Useful for redirecting after submission.</td></tr><tr><td><strong>Reload Page</strong></td><td>Refreshes the active web page.</td><td>Useful for resetting state or recovering from unexpected page rendering issues.</td></tr><tr><td><strong>Re-Execute Form</strong></td><td>Restarts the current form automation from the very first field.</td><td>Useful for retry loops after dynamic DOM reloads or validation resets.</td></tr><tr><td><strong>Click on Element</strong></td><td>Simulates a mouse click on a specified target selector or XPath.</td><td>Target element selector. Used to close modal popups, dismiss dialogs, or click confirmation buttons.</td></tr><tr><td><strong>Execute Segment</strong></td><td>Triggers execution of a modular, reusable routine.</td><td>Segment Name. Enables modular sub-routines (e.g., OTP entry, captcha solving, or address wizards).</td></tr><tr><td><strong>Set Local Data</strong></td><td>Stores a key-value pair in extension local memory.</td><td>Storage Key &amp; Value. Passes dynamic tokens or scraped values across fields and forms.</td></tr><tr><td><strong>Remove Local Data</strong></td><td>Deletes a stored key from extension local memory.</td><td>Storage Key. Cleans up temporary session flags or cache keys.</td></tr><tr><td><strong>Mark Entry As Saved</strong></td><td>Marks the active data row as completed in extension memory.</td><td>Prevents reprocessing the same spreadsheet record and updates the status indicator.</td></tr><tr><td><strong>Go to Next Entry</strong></td><td>Increments row index to fetch the next data record.</td><td>Automatically advances to the next spreadsheet row in batch processing routines.</td></tr><tr><td><strong>Skip Segment</strong></td><td>Bypasses remaining fields in the currently active segment.</td><td>Skips non-applicable branch logic inside reusable routines.</td></tr><tr><td><strong>Skip Form</strong></td><td>Aborts execution of remaining fields in the active form.</td><td>Skips subsequent form steps and transitions to the next form or loop iteration.</td></tr><tr><td><strong>Stop Loop</strong></td><td>Halts the active repeating loop sequence.</td><td>Immediately exits loop execution when a terminal condition or error is encountered.</td></tr></tbody></table><hr><h2 id="field-success-response-action" tabindex="-1">Field Success Response Action <a class="header-anchor" href="#field-success-response-action" aria-label="Permalink to “Field Success Response Action”">​</a></h2><p>The <strong>Success Response Action</strong> executes whenever a field operation completes without error.</p><img src="/image/field-success-response-action-01.png" alt="Field Success Response Action Interface" style="max-width:500px;border-radius:8px;margin:16px 0;"><h3 id="configuration-steps" tabindex="-1">Configuration Steps <a class="header-anchor" href="#configuration-steps" aria-label="Permalink to “Configuration Steps”">​</a></h3><ol><li>In the Field Settings sidebar, scroll to <strong>Response Action Settings</strong>.</li><li>Toggle ON <strong>Field Success Response Action</strong>.</li><li>Select your desired action from the dropdown menu (e.g., <code>Execute Segment</code>, <code>Click on Element</code>, or <code>Mark Entry As Saved</code>).</li><li>Provide any required parameter (such as the target selector or segment name).</li></ol><h3 id="common-use-cases" tabindex="-1">Common Use Cases <a class="header-anchor" href="#common-use-cases" aria-label="Permalink to “Common Use Cases”">​</a></h3><ul><li><strong>Triggering Submission</strong>: Click the &quot;Submit&quot; or &quot;Continue&quot; button immediately after filling the final form input.</li><li><strong>Dynamic Segment Branching</strong>: Run an auxiliary segment when an optional checkbox or toggle is successfully enabled.</li><li><strong>Data Persistence</strong>: Save a generated transaction ID into local storage with <strong>Set Local Data</strong>.</li></ul><hr><h2 id="field-error-response-action" tabindex="-1">Field Error Response Action <a class="header-anchor" href="#field-error-response-action" aria-label="Permalink to “Field Error Response Action”">​</a></h2><p>The <strong>Error Response Action</strong> executes when a field fails to execute (e.g., element not found within timeout, target element disabled, or network failure).</p><img src="/image/field-error-response-action-01.png" alt="Field Error Response Action Interface" style="max-width:500px;border-radius:8px;margin:16px 0;"><h3 id="configuration-steps-1" tabindex="-1">Configuration Steps <a class="header-anchor" href="#configuration-steps-1" aria-label="Permalink to “Configuration Steps”">​</a></h3><ol><li>In the Field Settings sidebar, scroll to <strong>Response Action Settings</strong>.</li><li>Toggle ON <strong>Field Error Response Action</strong>.</li><li>Select an error recovery action from the dropdown menu (e.g., <code>Reload Page</code>, <code>Click on Element</code>, or <code>Skip Form</code>).</li><li>Configure any associated target parameters.</li></ol><h3 id="common-use-cases-1" tabindex="-1">Common Use Cases <a class="header-anchor" href="#common-use-cases-1" aria-label="Permalink to “Common Use Cases”">​</a></h3><ul><li><strong>Self-Healing Automation</strong>: If a dynamic modal dialog blocks the input, use <strong>Click on Element</strong> to close the dialog.</li><li><strong>Graceful Degradation</strong>: If an optional element is missing, use <strong>Skip Form</strong> or log the error rather than crashing the workflow.</li><li><strong>Page Recovery</strong>: Trigger <strong>Reload Page</strong> if an asynchronous API call failed to populate necessary dropdown options.</li></ul><hr><h2 id="field-skip-response-action" tabindex="-1">Field Skip Response Action <a class="header-anchor" href="#field-skip-response-action" aria-label="Permalink to “Field Skip Response Action”">​</a></h2><p>The <strong>Skip Response Action</strong> executes whenever a field is deliberately bypassed by condition rules (such as value matching, text matching, or spreadsheet conditions).</p><img src="/image/field-skip-response-action-01.png" alt="Field Skip Response Action Interface" style="max-width:500px;border-radius:8px;margin:16px 0;"><h3 id="configuration-steps-2" tabindex="-1">Configuration Steps <a class="header-anchor" href="#configuration-steps-2" aria-label="Permalink to “Configuration Steps”">​</a></h3><ol><li>In the Field Settings sidebar, scroll to <strong>Response Action Settings</strong>.</li><li>Toggle ON <strong>Field Skip Response Action</strong>.</li><li>Select the follow-up behavior from the dropdown menu (e.g., <code>Execute Segment</code>, <code>Skip Segment</code>, or <code>Go to Next Entry</code>).</li></ol><h3 id="common-use-cases-2" tabindex="-1">Common Use Cases <a class="header-anchor" href="#common-use-cases-2" aria-label="Permalink to “Common Use Cases”">​</a></h3><ul><li><strong>Conditional Branching</strong>: If a primary field is skipped because the user selected &quot;Cash&quot; instead of &quot;Card&quot;, execute an alternate payment segment.</li><li><strong>Batch Processing Navigation</strong>: When a row has an empty identifier, trigger <strong>Go to Next Entry</strong> to advance cleanly to the next record.</li><li><strong>Form Skipping</strong>: If pre-requisite conditions are not met, skip the rest of the form with <strong>Skip Form</strong>.</li></ul><hr><h2 id="workflow-examples" tabindex="-1">Workflow Examples <a class="header-anchor" href="#workflow-examples" aria-label="Permalink to “Workflow Examples”">​</a></h2><h3 id="example-1-multi-step-wizard-progression" tabindex="-1">Example 1: Multi-Step Wizard Progression <a class="header-anchor" href="#example-1-multi-step-wizard-progression" aria-label="Permalink to “Example 1: Multi-Step Wizard Progression”">​</a></h3><ul><li><strong>Field</strong>: &quot;Last Name&quot; Input (Last field on Step 1)</li><li><strong>Success Action</strong>: <code>Click on Element</code> targeting <code>button#btn-next-step</code></li><li><strong>Result</strong>: Once the final field on Step 1 is filled, the extension automatically clicks &quot;Next&quot;, advancing to Step 2 without manual intervention.</li></ul><h3 id="example-2-error-recovery-with-popups" tabindex="-1">Example 2: Error Recovery with Popups <a class="header-anchor" href="#example-2-error-recovery-with-popups" aria-label="Permalink to “Example 2: Error Recovery with Popups”">​</a></h3><ul><li><strong>Field</strong>: &quot;Submit Order&quot; Button</li><li><strong>Error Action</strong>: <code>Click on Element</code> targeting <code>.modal-close-btn</code></li><li><strong>Result</strong>: If an unexpected promotional modal blocks the submit button, the error handler dismisses the modal.</li></ul><h3 id="example-3-segment-chaining-for-verification" tabindex="-1">Example 3: Segment Chaining for Verification <a class="header-anchor" href="#example-3-segment-chaining-for-verification" aria-label="Permalink to “Example 3: Segment Chaining for Verification”">​</a></h3><ul><li><strong>Field</strong>: &quot;Enter Verification Code&quot;</li><li><strong>Success Action</strong>: <code>Execute Segment</code> with value <code>Process-KYC-Approval</code></li><li><strong>Result</strong>: Successfully filling the code triggers the secondary KYC verification routine.</li></ul><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ol><li><strong>Avoid Infinite Loops</strong>: When using <code>Re-Execute Form</code> or <code>Reload Page</code> on error, ensure prerequisite conditions will change on reload to prevent infinite retry cycles.</li><li><strong>Combine with Timing Delays</strong>: For dynamic Single Page Applications (SPAs), set appropriate Before/After delays in <a href="/documentation/form-fields/field-settings.html#timing-position-settings">Field Settings</a> so DOM updates settle before response actions trigger.</li><li><strong>Monitor via Logs</strong>: Track response action triggers and status switches inside the built-in <a href="/documentation/logs.html">Logs</a> dashboard.</li></ol><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html">Form Field Overview</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html">Field Settings</a></li><li><img src="/svg/template.svg" class="doc-icon"> <a href="/documentation/segment.html">Segments Routine Automation</a></li><li><img src="/svg/beaker.svg" class="doc-icon"> <a href="/documentation/logs.html">Execution Logs &amp; Monitoring</a></li><li><img src="/svg/database.svg" class="doc-icon"> <a href="/documentation/form-fields/field-types.html">Field Types Reference</a></li></ul>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};